"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["30072"],{35918(e){e.exports=JSON.parse('{"id":"FIN-546","slug":"tax-refund","term":"Tax Refund","also_known_as":[],"difficulty":"Beginner","definition":"A tax refund is money returned by the tax authority to a taxpayer who paid more tax during the year than they actually owed.","explanation":["Refunds usually arise because tax is collected in advance, through withholding from wages or advance payments, based on estimates. When the final tax is calculated on the tax return, any overpayment is returned.","For example, if an employee had 7,200 withheld from their pay during the year but their tax return shows they owe only 6,500 after claiming deductions and credits, they receive a refund of 700.","Refunds can result from claiming deductions or credits not reflected in withholding, from changes in income during the year, from working only part of the year or from refundable tax credits.","A large refund may feel like a bonus, but it means the taxpayer effectively gave the government an interest-free loan during the year. Some people prefer to adjust their withholding so they keep more money in each paycheck and receive a smaller refund, or none at all.","Tax refund scams are common. Fraudsters may pose as tax authorities, promising refunds in exchange for personal or bank details. Genuine tax authorities generally do not ask for sensitive information by unsolicited message."],"note":"","total":1500,"prev":{"slug":"tax-provision","term":"Tax Provision"},"next":{"slug":"tax-residency","term":"Tax Residency"}}')}}]);